using Microsoft.EntityFrameworkCore;
namespace EduFlow.Api;

public class EduFlowDbContext(DbContextOptions<EduFlowDbContext> o) : DbContext(o) { public DbSet<User> Users => Set<User>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<Course> Courses => Set<Course>(); public DbSet<Enrollment> Enrollments => Set<Enrollment>(); public DbSet<Module> Modules => Set<Module>(); public DbSet<LearningMaterial> Materials => Set<LearningMaterial>(); public DbSet<Assignment> Assignments => Set<Assignment>(); public DbSet<Submission> Submissions => Set<Submission>(); public DbSet<Announcement> Announcements => Set<Announcement>(); public DbSet<ActivityLog> ActivityLogs => Set<ActivityLog>(); protected override void OnModelCreating(ModelBuilder b) { b.Entity<User>().HasIndex(x => x.Email).IsUnique(); b.Entity<Enrollment>().HasIndex(x => new { x.CourseId, x.StudentId }).IsUnique(); b.Entity<Course>().HasOne(x => x.Teacher).WithMany(x => x.TeachingCourses).HasForeignKey(x => x.TeacherId).OnDelete(DeleteBehavior.SetNull); b.Entity<Assignment>().HasOne(x => x.Module).WithMany(x => x.Assignments).HasForeignKey(x => x.ModuleId).OnDelete(DeleteBehavior.SetNull); } }
